INSERT INTO auth.identities (
  id,
  provider_id,
  user_id,
  identity_data,
  provider,
  last_sign_in_at,
  created_at,
  updated_at
)
SELECT
  gen_random_uuid(),
  u.id::text,
  u.id,
  jsonb_build_object('sub', u.id::text, 'email', u.email),
  'email'::text,
  now(),
  now(),
  now()
FROM auth.users AS u
WHERE u.email LIKE '%.seed@example.com'
ON CONFLICT DO NOTHING;

UPDATE public.profiles
SET display_name = v.name,
    avatar_url = NULL
FROM (VALUES
