  ('10000000-0000-4000-8000-000000000002'::uuid, '太郎'),
  ('10000000-0000-4000-8000-000000000003'::uuid, '次郎'),
  ('10000000-0000-4000-8000-000000000004'::uuid, '三郎'),
  ('10000000-0000-4000-8000-000000000005'::uuid, '静子'),
  ('10000000-0000-4000-8000-000000000006'::uuid, '憲太郎')
) AS v (id, name)
WHERE profiles.id = v.id;

